eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   search: () => (/* binding */ search)\n/* harmony export */ });\n/* harmony import */ var flexsearch__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! flexsearch */ \"(ssr)/./node_modules/flexsearch/dist/flexsearch.bundle.module.min.js\");\n\nlet sectionIndex = new flexsearch__WEBPACK_IMPORTED_MODULE_0__[\"default\"].Document({\n    tokenize: \"full\",\n    document: {\n        id: \"url\",\n        index: \"content\",\n        store: [\n            \"title\",\n            \"pageTitle\"\n        ]\n    },\n    context: {\n        resolution: 9,\n        depth: 2,\n        bidirectional: true\n    }\n});\nlet data = [\n    {\n        \"url\": \"/\",\n        \"sections\": [\n            [\n                \"FaceSign API Documentation\",\n                null,\n                [\n                    \"The FaceSign API enables developers to create AI-powered identity verification flows with conversational interfaces, biometric verification, document scanning, and multi-factor authentication.\",\n                    \"Quick Start\",\n                    \"Explore SDKs\"\n                ]\n            ],\n            [\n                \"Getting started\",\n                \"getting-started\",\n                [\n                    \"Create verification sessions, customize flows, and integrate identity verification in minutes.\"\n                ]\n            ],\n            [\n                \"What is FaceSign?\",\n                \"what-is-face-sign\",\n                [\n                    \"FaceSign is an AI-powered identity verification platform that helps businesses verify their users' identities through conversational interfaces, biometric verification, and document scanning. Our platform offers:\",\n                    \"Conversational AI Verification - Natural language interactions guided by AI avatars\",\n                    \"Biometric Authentication - Face recognition, liveness detection, and age estimation\",\n                    \"Document Verification - ID document scanning and authentication\",\n                    \"Multi-Factor Authentication - Email and SMS verification with OTP\",\n                    \"Customizable Flows - Visual node-based workflow builder\",\n                    \"Global Coverage - Support for multiple languages and regions\"\n                ]\n            ],\n            [\n                \"Key Features\",\n                \"key-features\",\n                [\n                    \"Node-Based Flow Builder\",\n                    \"Build complex verification workflows using our visual node system. Connect conversation nodes, biometric checks, document scanning, and more to create custom verification flows.\",\n                    \"Real-Time Verification\",\n                    \"Get instant verification results with our AI-powered analysis. Detect deepfakes, verify documents, and authenticate users in real-time.\",\n                    \"Developer-First API\",\n                    \"RESTful API with comprehensive SDKs for TypeScript, Python, and more. Built with modern standards including OpenAPI 3.0 specification.\"\n                ]\n            ],\n            [\n                \"Core Concepts\",\n                \"core-concepts\",\n                [\n                    \"Understand the fundamental building blocks of the FaceSign platform.\",\n                    \"Verification sessions are the core of FaceSign - learn how they work.\",\n                    \"Secure authentication tokens for end-user verification flows.\",\n                    \"Build complex verification flows using our visual node system.\"\n                ]\n            ],\n            [\n                \"API Resources\",\n                \"api-resources\",\n                [\n                    \"Explore the available API endpoints and resources.\",\n                    \"Create, retrieve, and manage verification sessions.\",\n                    \"Get supported languages for multi-lingual verification.\",\n                    \"Explore available AI avatars for conversational interfaces.\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/authentication\",\n        \"sections\": [\n            [\n                \"Authentication\",\n                null,\n                [\n                    \"The FaceSign API uses API keys to authenticate requests. You can view and manage your API keys in the FaceSign Dashboard. \"\n                ]\n            ],\n            [\n                \"API Keys\",\n                \"api-keys\",\n                [\n                    \"FaceSign provides two types of API keys:\",\n                    \"Test mode keys - Start with sk_test_ and can be used for development and testing\",\n                    \"Production mode keys - Start with sk_live_ and should be used in your production environment\",\n                    \"Test mode keys have the same capabilities as production keys but will not charge your account. All sessions created in test mode are clearly marked.\"\n                ]\n            ],\n            [\n                \"Getting your API keys\",\n                \"getting-your-api-keys\",\n                [\n                    \"Log in to your FaceSign Dashboard\",\n                    \"Navigate to Settings → API Keys\",\n                    \"Copy your API key for the appropriate environment\",\n                    \"Keep your API keys secure! Never commit them to version control or expose them in client-side code.\"\n                ]\n            ],\n            [\n                \"Using API keys\",\n                \"using-api-keys\",\n                [\n                    \"Include your API key in the Authorization header of every request:\"\n                ]\n            ],\n            [\n                \"Environment variables\",\n                \"environment-variables\",\n                [\n                    \"We strongly recommend using environment variables to store your API keys:\"\n                ]\n            ],\n            [\n                \"Client-side authentication\",\n                \"client-side-authentication\",\n                [\n                    \"For client-side integrations, use session-specific client secrets instead of your API key:\"\n                ]\n            ],\n            [\n                \"Rate limiting\",\n                \"rate-limiting\",\n                [\n                    \"API requests are rate limited to ensure fair usage:\",\n                    \"Test mode: 100 requests per minute\",\n                    \"Production mode: 1000 requests per minute\",\n                    \"If you exceed the rate limit, you'll receive a 429 Too Many Requests response:\"\n                ]\n            ],\n            [\n                \"API versioning\",\n                \"api-versioning\",\n                [\n                    \"The FaceSign API uses date-based versioning. You can specify the API version using the FaceSign-Version header:\",\n                    \"If you don't specify a version, your requests will use the API version that was current when your account was created.\"\n                ]\n            ],\n            [\n                \"Security best practices\",\n                \"security-best-practices\",\n                [\n                    \"Never expose your API keys - Keep them server-side only\",\n                    \"Use environment variables - Don't hardcode keys in your source code\",\n                    \"Rotate keys regularly - Generate new keys periodically\",\n                    \"Use test keys for development - Keep production keys secure\",\n                    \"Monitor key usage - Check your dashboard for unusual activity\"\n                ]\n            ],\n            [\n                \"Webhook signatures\",\n                \"webhook-signatures\",\n                [\n                    \"For webhook endpoints, verify the signature to ensure requests are from FaceSign:\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Now that you understand authentication, you're ready to start making API requests:\",\n                    \"Follow the quick start guide\",\n                    \"Learn about sessions\",\n                    \"Understand error handling\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/avatars\",\n        \"sections\": [\n            [\n                \"Avatars\",\n                null,\n                [\n                    \"FaceSign uses AI-powered avatars to create natural, conversational verification experiences. These virtual assistants guide users through the verification process with human-like interactions, making the experience more engaging and less intimidating than traditional forms. \"\n                ]\n            ],\n            [\n                \"How avatars work\",\n                \"how-avatars-work\",\n                [\n                    \"FaceSign avatars are AI-powered virtual assistants that:\",\n                    \"Guide users through each step of the verification process\",\n                    \"Adapt their conversation based on the verification modules you've configured\",\n                    \"Speak multiple languages and adjust their communication style accordingly\",\n                    \"Provide real-time feedback and help users complete verification successfully\",\n                    \"Detect emotions and engagement to provide a more personalized experience\"\n                ]\n            ],\n            [\n                \"Avatar object\",\n                \"avatar-object\",\n                [\n                    \"Unique identifier for the avatar.\",\n                    \"Human-readable name of the avatar.\",\n                    \"Avatar gender: male, female, or unknown.\",\n                    \"URL to the avatar's profile image for display in your interface.\"\n                ]\n            ],\n            [\n                \"Get available avatars \",\n                \"get-available-avatars\",\n                [\n                    \"Returns a list of all available AI avatars that can be used in verification sessions. Choose an avatar that best fits your brand and target audience.\"\n                ]\n            ],\n            [\n                \"Choosing the right avatar\",\n                \"choosing-the-right-avatar\",\n                [\n                    \"Consider your audience\",\n                    \"Different avatars work better for different use cases and audiences:\",\n                    \"Dynamic avatar selection\",\n                    \"You can dynamically select avatars based on user preferences or demographics:\"\n                ]\n            ],\n            [\n                \"Avatar customization\",\n                \"avatar-customization\",\n                [\n                    \"Custom phrases\",\n                    \"Customize how your avatar greets and concludes the verification:\",\n                    \"Brand-specific customization\",\n                    \"Adapt the avatar's messaging to match your brand:\"\n                ]\n            ],\n            [\n                \"Avatar selection UI\",\n                \"avatar-selection-ui\",\n                [\n                    \"Let users choose their avatar\",\n                    \"Provide an avatar selection interface before starting verification:\",\n                    \"Preview avatar interactions\",\n                    \"Show users what to expect from their chosen avatar:\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"1. Match avatar to brand personality\",\n                    \"Choose avatars that align with your brand's personality and values:\",\n                    \"2. Consider cultural sensitivity\",\n                    \"Be mindful of cultural preferences when selecting avatars for different markets:\",\n                    \"3. Test avatar effectiveness\",\n                    \"Monitor how different avatars perform with your users:\",\n                    \"4. Cache avatar data\",\n                    \"Cache avatar information to improve performance:\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Sessions - Learn how to create sessions with avatar configuration\",\n                    \"Languages - Configure multi-language support for your avatars\",\n                    \"Modules - Understand how avatars adapt to different verification modules\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/client-secrets\",\n        \"sections\": [\n            [\n                \"Client Secrets\",\n                null,\n                [\n                    \"Client secrets are secure, session-specific tokens that allow your frontend applications to interact with FaceSign's verification interface. Unlike your API key, client secrets are safe to use in client-side code and are automatically included when you create or retrieve a session. \"\n                ]\n            ],\n            [\n                \"How client secrets work\",\n                \"how-client-secrets-work\",\n                [\n                    \"Client secrets provide a secure way to authenticate frontend requests:\",\n                    \"Server-side session creation - Use your API key to create a session\",\n                    \"Client secret returned - FaceSign returns a session-specific client secret\",\n                    \"Frontend integration - Pass the client secret to your frontend or mobile app\",\n                    \"Secure verification - Frontend uses the client secret to access the verification interface\",\n                    \"Automatic expiration - Client secrets expire after 1 hour for security\"\n                ]\n            ],\n            [\n                \"Client secret properties\",\n                \"client-secret-properties\",\n                [\n                    \"The client secret token to use in frontend integrations.\",\n                    \"Unix timestamp when the client secret was created.\",\n                    \"Unix timestamp when the client secret expires (1 hour from creation).\",\n                    \"Pre-built URL for hosted verification flow including the client secret.\"\n                ]\n            ],\n            [\n                \"Using client secrets\",\n                \"using-client-secrets\",\n                [\n                    \"Web integration\",\n                    \"For web applications, you can either redirect users to the hosted flow or use the JavaScript SDK:\",\n                    \"Mobile integration\",\n                    \"For mobile applications, use the native SDKs:\"\n                ]\n            ],\n            [\n                \"Security considerations\",\n                \"security-considerations\",\n                [\n                    \"Client secrets are safe for frontend use\",\n                    \"Unlike API keys, client secrets are designed to be safe for client-side use:\",\n                    \"Session-specific - Each client secret is tied to a single session\",\n                    \"Time-limited - Automatically expire after 1 hour\",\n                    \"Read-only - Cannot be used to create new sessions or access other data\",\n                    \"Domain-restricted - Can be restricted to specific domains (contact support)\",\n                    \"Best practices\",\n                    \"Fetch on demand - Get client secrets from your backend when needed\",\n                    \"Handle expiration - Refresh client secrets if they expire during verification\",\n                    \"Secure transmission - Always use HTTPS when transmitting client secrets\",\n                    \"Don't store long-term - Client secrets are meant for immediate use\",\n                    \"Handling expiration\",\n                    \"Client secrets expire after 1 hour. If verification takes longer or you need to restart the process:\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Sessions - Learn about the session lifecycle\",\n                    \"Webhooks - Get real-time updates about verification progress\",\n                    \"Modules - Configure verification modules for your use case\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/errors\",\n        \"sections\": [\n            [\n                \"Error Handling\",\n                null,\n                [\n                    \"The FaceSign API uses conventional HTTP response codes to indicate the success or failure of an API request. Understanding these errors and implementing proper error handling is crucial for building a robust integration. \"\n                ]\n            ],\n            [\n                \"HTTP status codes\",\n                \"http-status-codes\",\n                [\n                    \"FaceSign returns the following HTTP status codes:\",\n                    \"The request was successful.\",\n                    \"The resource was successfully created.\",\n                    \"The request was invalid or cannot be served. Check the error message for details.\",\n                    \"The request requires authentication or the API key is invalid.\",\n                    \"The API key doesn't have permissions to perform the request.\",\n                    \"The requested resource doesn't exist.\",\n                    \"The request conflicts with another request (perhaps using the same idempotency key).\",\n                    \"Too many requests hit the API too quickly. We recommend implementing exponential backoff.\",\n                    \"Something went wrong on FaceSign's end. These are rare.\"\n                ]\n            ],\n            [\n                \"Error response format\",\n                \"error-response-format\",\n                [\n                    \"All error responses follow a consistent format:\",\n                    \"Error object properties\",\n                    \"The type of error returned. See error types below.\",\n                    \"A human-readable message providing more details about the error.\",\n                    \"The parameter the error relates to if the error is parameter-specific.\",\n                    \"A short string uniquely identifying the problem.\"\n                ]\n            ],\n            [\n                \"Error types\",\n                \"error-types\",\n                [\n                    \"API errors cover any other type of problem (e.g., a temporary problem with FaceSign's servers).\",\n                    \"Failure to properly authenticate in the request.\",\n                    \"Invalid request errors arise when your request has invalid parameters.\",\n                    \"Too many requests hit the API too quickly.\",\n                    \"Errors triggered by our validation system (e.g., invalid email format).\"\n                ]\n            ],\n            [\n                \"Handling errors\",\n                \"handling-errors\",\n                [\n                    \"Here's how to properly handle errors in your integration:\"\n                ]\n            ],\n            [\n                \"Common errors and solutions\",\n                \"common-errors-and-solutions\",\n                [\n                    \"Authentication errors\",\n                    \"Solution: Check that you're using the correct API key and that it hasn't been revoked.\",\n                    \"Invalid request errors\",\n                    \"Solution: Ensure all required parameters are included in your request.\",\n                    \"Rate limit errors\",\n                    \"Solution: Implement exponential backoff and respect the Retry-After header.\"\n                ]\n            ],\n            [\n                \"Implementing retry logic\",\n                \"implementing-retry-logic\",\n                [\n                    \"For transient errors and rate limiting, implement exponential backoff:\"\n                ]\n            ],\n            [\n                \"Idempotency\",\n                \"idempotency\",\n                [\n                    \"To safely retry requests without accidentally performing the same operation twice, use idempotency keys:\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"Always handle errors gracefully - Don't let API errors crash your application\",\n                    \"Log errors for debugging - Include request IDs for easier troubleshooting\",\n                    \"Implement retry logic - Use exponential backoff for transient errors\",\n                    \"Respect rate limits - Monitor your usage and implement proper throttling\",\n                    \"Use idempotency keys - Prevent duplicate operations when retrying\",\n                    \"Show user-friendly messages - Don't expose technical error details to end users\"\n                ]\n            ],\n            [\n                \"Getting help\",\n                \"getting-help\",\n                [\n                    \"If you encounter persistent errors:\",\n                    \"Check the API status page for any ongoing issues\",\n                    \"Review your request parameters against the API documentation\",\n                    \"Contact support with the request ID from the error response\",\n                    \"Review authentication\",\n                    \"Set up webhooks\",\n                    \"Learn about rate limits\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/languages\",\n        \"sections\": [\n            [\n                \"Languages\",\n                null,\n                [\n                    \"FaceSign supports multiple languages for the verification interface, allowing you to provide a localized experience for users worldwide. The /langs endpoint returns all available languages that can be used in your verification sessions. \"\n                ]\n            ],\n            [\n                \"Supported languages\",\n                \"supported-languages\",\n                [\n                    \"FaceSign currently supports the following languages:\",\n                    \"English (en) - Default language\",\n                    \"Spanish (es) - Espa\\xf1ol\",\n                    \"French (fr) - Fran\\xe7ais\",\n                    \"German (de) - Deutsch\",\n                    \"Italian (it) - Italiano\",\n                    \"Portuguese (pt) - Portugu\\xeas\",\n                    \"Dutch (nl) - Nederlands\",\n                    \"Polish (pl) - Polski\",\n                    \"Russian (ru) - Русский\",\n                    \"Japanese (ja) - 日本語\",\n                    \"Korean (ko) - 한국어\",\n                    \"Chinese Simplified (zh-CN) - 简体中文\",\n                    \"Chinese Traditional (zh-TW) - 繁體中文\"\n                ]\n            ],\n            [\n                \"Language object\",\n                \"language-object\",\n                [\n                    \"Language code (ISO 639-1 format).\",\n                    \"Human-readable language name in the language itself.\"\n                ]\n            ],\n            [\n                \"Get supported languages \",\n                \"get-supported-languages\",\n                [\n                    \"Returns a list of all languages supported by FaceSign. Use these language codes when creating sessions to specify which languages should be available to users.\"\n                ]\n            ],\n            [\n                \"Using languages in sessions\",\n                \"using-languages-in-sessions\",\n                [\n                    \"Basic language configuration\",\n                    \"When creating a session, you can specify which languages should be available and set a default language:\",\n                    \"Dynamic language selection\",\n                    \"You can dynamically select languages based on user preferences or browser settings:\",\n                    \"Regional considerations\",\n                    \"Consider your target markets when selecting languages:\"\n                ]\n            ],\n            [\n                \"Language selection UX\",\n                \"language-selection-ux\",\n                [\n                    \"Let users choose their language\",\n                    \"Provide a language selector in your frontend before starting verification:\",\n                    \"Auto-detect user language\",\n                    \"Automatically detect and use the user's browser language:\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"1. Cache language list\",\n                    \"Cache the languages list to avoid unnecessary API calls:\",\n                    \"2. Provide language fallbacks\",\n                    \"Always include common languages as fallbacks:\",\n                    \"3. Handle RTL languages\",\n                    \"For right-to-left languages, ensure your UI adapts accordingly:\",\n                    \"4. Store user language preference\",\n                    \"Remember user language choices for future sessions:\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Sessions - Learn how to create sessions with language configuration\",\n                    \"Avatars - Discover available AI avatars for different languages\",\n                    \"Modules - Configure verification modules for specific regions\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/modules\",\n        \"sections\": [\n            [\n                \"Verification Modules\",\n                null,\n                [\n                    \"FaceSign offers a comprehensive suite of verification modules that you can mix and match to create the perfect verification flow for your use case. Each module handles a specific type of verification, from email and SMS to advanced biometric analysis and document authentication.\"\n                ]\n            ],\n            [\n                \"Available modules\",\n                \"available-modules\",\n                [\n                    \"FaceSign provides seven core verification modules:\",\n                    \"Email Verification\\nVerify user email addresses with OTP codes\\nLearn more →\",\n                    \"SMS Verification\\nSend verification codes via SMS\\nLearn more →\",\n                    \"Identity Verification\\nFull biometric identity verification with liveness detection\\nLearn more →\",\n                    \"Document Authentication\\nScan and authenticate government-issued documents\\nLearn more →\",\n                    \"Age Estimation\\nAI-powered age verification and estimation\\nLearn more →\",\n                    \"Proof of Intent\\nCapture and verify user consent and intent\\nLearn more →\",\n                    \"Knowledge Verify\\nKnowledge-based authentication questions\\nLearn more →\"\n                ]\n            ],\n            [\n                \"Module types\",\n                \"module-types\",\n                [\n                    \"Each module has a specific type identifier that you use when configuring sessions:\",\n                    \"Email OTP verification module\",\n                    \"SMS OTP verification module\",\n                    \"Biometric identity verification with face scanning\",\n                    \"Government document scanning and authentication\",\n                    \"AI-powered age verification and estimation\",\n                    \"User consent and intent verification\",\n                    \"Knowledge-based authentication questions\"\n                ]\n            ],\n            [\n                \"Configuring modules\",\n                \"configuring-modules\",\n                [\n                    \"Basic module configuration\",\n                    \"Include modules in your session by adding them to the modules array:\",\n                    \"Module-specific configuration\",\n                    \"Many modules accept additional configuration options:\"\n                ]\n            ],\n            [\n                \"Common module combinations\",\n                \"common-module-combinations\",\n                [\n                    \"Basic identity verification\",\n                    \"Perfect for user onboarding and account verification:\",\n                    \"Financial services KYC\",\n                    \"Comprehensive verification for financial applications:\",\n                    \"Age-restricted services\",\n                    \"For platforms requiring age verification:\",\n                    \"High-security applications\",\n                    \"Maximum security for sensitive applications:\",\n                    \"Quick social verification\",\n                    \"Lightweight verification for social platforms:\"\n                ]\n            ],\n            [\n                \"Dynamic module selection\",\n                \"dynamic-module-selection\",\n                [\n                    \"User-based module selection\",\n                    \"Choose modules based on user characteristics:\",\n                    \"Risk-based module selection\",\n                    \"Adjust verification requirements based on risk assessment:\"\n                ]\n            ],\n            [\n                \"Module sequencing\",\n                \"module-sequencing\",\n                [\n                    \"Sequential vs. parallel verification\",\n                    \"FaceSign automatically handles module sequencing for optimal user experience:\",\n                    \"Conditional module activation\",\n                    \"Use custom flows to activate modules based on previous results:\"\n                ]\n            ],\n            [\n                \"Module results and data\",\n                \"module-results-and-data\",\n                [\n                    \"Accessing verification results\",\n                    \"Each module provides specific data in the session report:\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"1. Start simple, add complexity gradually\",\n                    \"Begin with basic modules and add more based on your needs:\",\n                    \"2. Consider user experience\",\n                    \"Balance security with user experience:\",\n                    \"3. Match modules to use case\",\n                    \"Choose modules that make sense for your application:\",\n                    \"4. Handle module failures gracefully\",\n                    \"Provide fallback options when modules fail:\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Explore individual module documentation for detailed configuration options:\",\n                    \"Email Verification - Configure email OTP verification\",\n                    \"SMS Verification - Set up SMS-based verification\",\n                    \"Identity Verification - Biometric verification setup\",\n                    \"Document Authentication - Government document verification\",\n                    \"Age Estimation - AI-powered age verification\",\n                    \"Proof of Intent - User consent and intent capture\",\n                    \"Knowledge Verify - Knowledge-based authentication\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/quickstart\",\n        \"sections\": [\n            [\n                \"Quick Start\",\n                null,\n                [\n                    \"This guide will help you get started with the FaceSign API. You'll learn how to create your first verification session and integrate identity verification into your application. \",\n                    \"You'll need a FaceSign account to follow this guide. Sign up if you haven't already.\"\n                ]\n            ],\n            [\n                \"Get your API keys\",\n                \"get-your-api-keys\",\n                [\n                    \"First, you'll need to get your API keys from the FaceSign dashboard.\",\n                    \"Log in to your FaceSign dashboard\",\n                    \"Navigate to Settings → API Keys\",\n                    \"Copy your API key (starts with sk_test_ for test mode or sk_live_ for production)\",\n                    \"Keep your API keys secure and never expose them in client-side code. Use environment variables to store them safely.\"\n                ]\n            ],\n            [\n                \"Install the SDK\",\n                \"install-the-sdk\",\n                [\n                    \"Choose your preferred language and install the FaceSign SDK:\"\n                ]\n            ],\n            [\n                \"Create your first session\",\n                \"create-your-first-session\",\n                [\n                    \"Now let's create a verification session. Sessions are the core of FaceSign - they represent a single identity verification flow.\"\n                ]\n            ],\n            [\n                \"Redirect your user\",\n                \"redirect-your-user\",\n                [\n                    \"After creating a session, you'll receive a response with a url field. Redirect your user to this URL to start the verification process:\"\n                ]\n            ],\n            [\n                \"Handle the result\",\n                \"handle-the-result\",\n                [\n                    \"After the user completes or cancels the verification, they'll be redirected to your success_url or cancel_url with the session ID as a query parameter:\",\n                    \"You can then retrieve the session to check the verification status:\"\n                ]\n            ],\n            [\n                \"What's next?\",\n                \"whats-next\",\n                [\n                    \"Congratulations! You've created your first verification session. Here are some next steps:\",\n                    \"Learn more about sessions\",\n                    \"Set up webhooks for real-time updates\",\n                    \"Customize your verification flow\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/sdks\",\n        \"sections\": [\n            [\n                \"Protocol SDKs\",\n                null,\n                [\n                    \"The recommended way to interact with the Protocol API is by using one of our official SDKs. Today, Protocol offers fine-tuned JavaScript, Ruby, PHP, Python, and Go libraries to make your life easier and give you the best experience when consuming the API. \"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/sessions\",\n        \"sections\": [\n            [\n                \"Sessions\",\n                null,\n                [\n                    \"Sessions are the core of FaceSign's identity verification platform. A session represents a single identity verification flow that guides users through various verification steps like conversational AI interactions, biometric checks, document scanning, and multi-factor authentication. \"\n                ]\n            ],\n            [\n                \"How FaceSign Sessions Work\",\n                \"how-face-sign-sessions-work\",\n                [\n                    \"FaceSign sessions work similarly to how Stripe handles payments. When you integrate FaceSign:\",\n                    \"Create a session using the FaceSign API and get a session object + client secret\",\n                    \"Save the session to your own database for tracking\",\n                    \"Provide the client secret to the FaceSign frontend (web or mobile)\",\n                    \"Listen for webhooks that inform you about session progress and completion\",\n                    \"Update your database when webhooks arrive with the latest session status\",\n                    \"Build your app logic using the session data stored in your database\",\n                    \"This approach gives you several benefits:\",\n                    \"Faster performance - No need to call external APIs repeatedly\",\n                    \"Better reliability - Your app doesn't depend on external API availability\",\n                    \"Enhanced control - All verification data is available in your database for queries and business logic\",\n                    \"Audit trail - Complete history of verification attempts and results\"\n                ]\n            ],\n            [\n                \"The session model\",\n                \"the-session-model\",\n                [\n                    \"The session model contains all the information about a verification session, including its configuration, status, and results.\",\n                    \"Properties\",\n                    \"Unique identifier for the session.\",\n                    \"Unix timestamp when the session was created.\",\n                    \"Unix timestamp when the user began the verification flow.\",\n                    \"Unix timestamp when the session was completed or cancelled.\",\n                    \"Current status: requiresInput, processing, complete, or canceled.\",\n                    \"Configuration object containing modules, customization, and flow settings.\",\n                    \"API version used for this session.\",\n                    \"Results of the verification including AI analysis, extracted data, and verification status.\",\n                    \"Session Settings\",\n                    \"Your internal reference ID to link this session to your user.\",\n                    \"Key-value pairs for storing additional information about the session.\",\n                    \"Optional custom greeting message for the AI avatar.\",\n                    \"Optional custom closing message for the AI avatar.\",\n                    \"Pre-filled data to pass to the verification flow.\",\n                    \"ID of the AI avatar to use for conversational interactions.\",\n                    \"Array of supported language codes for this session.\",\n                    \"Default language code if user's preference isn't available.\",\n                    \"Geographic zone: es (United States) or eu (European Union).\",\n                    \"Array of verification modules to include in this session.\",\n                    \"Custom node-based flow definition (optional).\",\n                    \"UI customization options including colors, fonts, and branding.\",\n                    \"Session Report\",\n                    \"When a session is completed, the report object contains detailed verification results:\",\n                    \"Conversation transcript between user and AI avatar.\",\n                    \"AI-powered analysis including age estimation, gender detection, and authenticity assessment.\",\n                    \"User's location information (if available and consented).\",\n                    \"Device information and browser details.\",\n                    \"Whether liveness was detected during biometric verification.\",\n                    \"Language used during the verification session.\",\n                    \"Data extracted from documents or user input during verification.\",\n                    \"Array of screenshot URLs captured during verification.\",\n                    \"URLs for avatar and user video recordings.\",\n                    \"Overall verification result - true if verification was successful.\"\n                ]\n            ],\n            [\n                \"Create a session \",\n                \"create-a-session\",\n                [\n                    \"Creates a new verification session. The response includes both the session object and a client secret for frontend integration.\",\n                    \"Required attributes\",\n                    \"Your internal reference ID to link this session to your user.\",\n                    \"Array of verification modules to include. Each module has a type and configuration options.\",\n                    \"Optional attributes\",\n                    \"Key-value pairs for storing additional information about the session.\",\n                    \"Custom greeting message for the AI avatar.\",\n                    \"Custom closing message for the AI avatar.\",\n                    \"Pre-filled data to pass to the verification flow.\",\n                    \"ID of the AI avatar to use. Get available avatars from /avatars endpoint.\",\n                    \"Array of supported language codes. Get available languages from /langs endpoint.\",\n                    \"Default language code (defaults to 'en').\",\n                    \"Geographic zone: es or eu (defaults to 'es').\",\n                    \"Custom node-based flow definition for advanced use cases.\",\n                    \"UI customization options including colors and branding.\"\n                ]\n            ],\n            [\n                \"Retrieve a session \",\n                \"retrieve-a-session\",\n                [\n                    \"Retrieves the details of an existing session, including any verification results if the session has been completed.\"\n                ]\n            ],\n            [\n                \"Refresh client secret \",\n                \"refresh-client-secret\",\n                [\n                    \"Generates a new client secret for an existing session. This is useful if the original client secret has expired or been compromised. Note that old client secrets are immediately invalidated when a new one is generated.\"\n                ]\n            ],\n            [\n                \"Session lifecycle\",\n                \"session-lifecycle\",\n                [\n                    \"Understanding the session lifecycle helps you build a robust integration. Here's how sessions progress through their states:\",\n                    \"Session statuses\",\n                    \"requiresInput - Session created, waiting for user to begin verification\",\n                    \"processing - User is actively going through the verification flow\",\n                    \"complete - Verification finished (check report.isVerified for success/failure)\",\n                    \"canceled - Session was cancelled by user or expired\",\n                    \"Handling results with webhooks\",\n                    \"The recommended approach is to use webhooks to get real-time updates about session status changes:\"\n                ]\n            ],\n            [\n                \"Integration best practices\",\n                \"integration-best-practices\",\n                [\n                    \"1. Database-First Approach\",\n                    \"Store session data in your database immediately after creation:\",\n                    \"2. Use Webhooks for Real-Time Updates\",\n                    \"Don't poll the API for session updates. Use webhooks instead:\",\n                    \"3. Handle Client Secret Expiration\",\n                    \"Client secrets expire after 1 hour. Handle expiration gracefully:\",\n                    \"4. Link Sessions to Your Users\",\n                    \"Always use clientReferenceId to link sessions to your users:\",\n                    \"5. Build Logic on Your Database\",\n                    \"Query your own database for verification status, don't call the API repeatedly:\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/webhooks\",\n        \"sections\": [\n            [\n                \"Webhooks\",\n                null,\n                [\n                    \"Webhooks allow you to receive real-time HTTP notifications when events happen in your FaceSign account. Rather than polling the API for updates, webhooks push data to your endpoint as soon as an event occurs. \"\n                ]\n            ],\n            [\n                \"Setting up webhooks\",\n                \"setting-up-webhooks\",\n                [\n                    \"To start receiving webhooks:\",\n                    \"Create an endpoint on your server to receive webhook events\",\n                    \"Register your endpoint URL in the FaceSign Dashboard\",\n                    \"Handle incoming webhook events in your application\",\n                    \"Creating a webhook endpoint\",\n                    \"Your webhook endpoint should:\",\n                    \"Accept POST requests with JSON payloads\",\n                    \"Respond quickly with a 2xx status code\",\n                    \"Verify the webhook signature for security\"\n                ]\n            ],\n            [\n                \"Webhook events\",\n                \"webhook-events\",\n                [\n                    \"FaceSign sends the following webhook events:\",\n                    \"Session events\",\n                    \"Sent when a new verification session is created.\",\n                    \"Sent when a user begins the verification process.\",\n                    \"Sent when a session is successfully verified.\",\n                    \"Sent when verification fails (e.g., document rejected, face mismatch).\",\n                    \"Sent when a session is cancelled by the user or via API.\",\n                    \"Sent when a session expires without completion.\",\n                    \"Event object structure\",\n                    \"All webhook events follow this structure:\"\n                ]\n            ],\n            [\n                \"Verifying webhook signatures\",\n                \"verifying-webhook-signatures\",\n                [\n                    \"FaceSign signs all webhook payloads so you can verify they're authentic. The signature is included in the FaceSign-Signature header.\",\n                    \"Always use a timing-safe comparison function to prevent timing attacks when verifying signatures.\"\n                ]\n            ],\n            [\n                \"Handling webhooks\",\n                \"handling-webhooks\",\n                [\n                    \"Best practices\",\n                    \"Respond quickly - Return a 2xx status code as soon as possible\",\n                    \"Process asynchronously - Use a queue for time-consuming operations\",\n                    \"Handle duplicates - Use the event ID to ensure idempotency\",\n                    \"Verify signatures - Always verify the webhook signature\",\n                    \"Handle failures gracefully - Implement proper error handling\",\n                    \"Retries\",\n                    \"FaceSign will retry failed webhook deliveries with exponential backoff:\",\n                    \"First retry: 5 seconds\",\n                    \"Second retry: 30 seconds\",\n                    \"Third retry: 2 minutes\",\n                    \"Fourth retry: 10 minutes\",\n                    \"Fifth retry: 1 hour\",\n                    \"After 5 failed attempts, the webhook is marked as failed and won't be retried.\",\n                    \"Testing webhooks\",\n                    \"You can test your webhook endpoint using the FaceSign Dashboard:\",\n                    \"Go to Settings → Webhooks\",\n                    \"Click on your webhook endpoint\",\n                    \"Click Send test webhook\",\n                    \"Select an event type and click Send\"\n                ]\n            ],\n            [\n                \"Example: Complete webhook handler\",\n                \"example-complete-webhook-handler\",\n                [\n                    \"Here's a complete example that handles all session events:\"\n                ]\n            ],\n            [\n                \"Webhook security\",\n                \"webhook-security\",\n                [\n                    \"IP allowlisting\",\n                    \"For additional security, you can restrict webhook requests to FaceSign's IP addresses:\",\n                    \"Request headers\",\n                    \"All webhook requests include these headers:\",\n                    \"HMAC signature of the request body\",\n                    \"Unique identifier for this event\",\n                    \"Always application/json\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Now that you understand webhooks, explore these related topics:\",\n                    \"Learn about sessions\",\n                    \"Handle errors properly\",\n                    \"Customize verification flows\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/modules/age-estimation\",\n        \"sections\": [\n            [\n                \"Age Estimation Module\",\n                null,\n                [\n                    \"The Age Estimation module uses AI to estimate a person's age from their face. It provides a fast, privacy-friendly way to verify that users meet minimum age requirements without needing to collect identity documents. This is ideal for age-gated content, products, or services.\"\n                ]\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"Initiate session - Create a session with the ageEstimation module, specifying the minimum required age.\",\n                    \"User consent - The user grants access to their camera.\",\n                    \"Facial analysis - The user looks into the camera, and FaceSign's AI analyzes their facial features to estimate an age range.\",\n                    \"Liveness detection - A built-in liveness check ensures the person is real and present.\",\n                    \"Verification complete - The module returns an age range estimate and a true or false result based on the required age.\"\n                ]\n            ],\n            [\n                \"Module configuration\",\n                \"module-configuration\",\n                [\n                    \"Properties\",\n                    \"Must be ageEstimation.\",\n                    \"The minimum required age for the verification to pass.\"\n                ]\n            ],\n            [\n                \"Example implementation\",\n                \"example-implementation\",\n                [\n                    \"Age verification for a gaming platform\",\n                    \"Verify that users are at least 13 years old to comply with COPPA.\",\n                    \"Age verification for an 18+ service\",\n                    \"Ensure users are over 18 for an age-restricted service.\"\n                ]\n            ],\n            [\n                \"User experience\",\n                \"user-experience\",\n                [\n                    \"The user experience is fast and frictionless. The user simply looks at the camera for a few seconds.\",\n                    \"Age estimation user experience\"\n                ]\n            ],\n            [\n                \"Handling verification results\",\n                \"handling-verification-results\",\n                [\n                    \"Webhook event\",\n                    \"The session.completed webhook report contains the AI's analysis, including the estimated age range and the overall verification result.\",\n                    \"Backend logic\",\n                    \"Use the webhook to grant or deny access based on the age verification result.\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"1. Privacy-first approach\",\n                    \"Age Estimation is less intrusive than asking for an ID document. Position it as a quick, easy, and private way to verify age. No personal data is stored beyond the result of the check.\",\n                    \"2. Provide fallback options\",\n                    \"For users who are near the age threshold or who fail the estimation, provide a fallback method like documentAuthentication to ensure they are not unfairly blocked.\",\n                    \"3. Communicate results clearly\",\n                    'If a user fails the age check, provide a clear and helpful message. Avoid accusatory language. For example: \"Our system could not confirm you meet the age requirement. Please try verifying with a valid ID document.\"',\n                    \"4. Accuracy and bias\",\n                    \"FaceSign's AI is trained on a diverse, global dataset to ensure high accuracy and minimize bias across different demographics. The system provides an age range to account for potential variations.\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Document Authentication - Use as a fallback for age verification\",\n                    \"Identity Verification - Perform full biometric identity checks\",\n                    \"Custom Flows - Build advanced flows with conditional logic for age checks\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/modules/document-authentication\",\n        \"sections\": [\n            [\n                \"Document Authentication Module\",\n                null,\n                [\n                    \"The Document Authentication module allows you to scan, parse, and verify government-issued identity documents like driver's licenses, passports, and national ID cards. It uses OCR (Optical Character Recognition) and AI to extract data, check for tampering, and authenticate the document's validity.\"\n                ]\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"Initiate session - Create a session with the documentAuthentication module.\",\n                    \"User selects document - The user chooses the type of document they want to scan.\",\n                    \"Capture document - The interface guides the user to capture a clear image of the front and back of the document.\",\n                    \"AI-powered analysis - FaceSign's AI processes the images to:\",\n                    \"Extract personal information (name, DOB, address, etc.)\",\n                    \"Check for signs of tampering or forgery\",\n                    \"Verify holograms, watermarks, and other security features\",\n                    \"Verification complete - The module completes with the extracted data and an authentication result.\"\n                ]\n            ],\n            [\n                \"Module configuration\",\n                \"module-configuration\",\n                [\n                    \"Properties\",\n                    \"Must be documentAuthentication.\",\n                    \"This module has no additional configuration properties. Its behavior is determined by the document type selected by the user.\"\n                ]\n            ],\n            [\n                \"Example implementation\",\n                \"example-implementation\",\n                [\n                    \"Standard document authentication\",\n                    \"Add the documentAuthentication module to your session to enable ID document scanning.\"\n                ]\n            ],\n            [\n                \"User experience\",\n                \"user-experience\",\n                [\n                    \"Document selection\",\n                    \"The user selects the country and type of document they will provide.\",\n                    \"Document selection screen\",\n                    \"Document capture\",\n                    \"The interface guides the user to take a clear, well-lit photo of their document.\",\n                    \"Document capture screen\",\n                    \"Data confirmation\",\n                    \"The user is shown the extracted data and asked to confirm its accuracy.\",\n                    \"Document data confirmation\"\n                ]\n            ],\n            [\n                \"Handling verification results\",\n                \"handling-verification-results\",\n                [\n                    \"Webhook event\",\n                    \"The session.completed webhook contains the extracted data in the report.extractedData field.\",\n                    \"Backend logic\",\n                    \"Use the webhook to populate user profiles or fulfill compliance requirements.\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"1. Combine with Identity Verification for KYC\",\n                    'The most powerful use of this module is in combination with identityVerification. This allows you to perform a \"face match,\" comparing the live person to the photo on their ID document, which is a standard requirement for KYC/AML compliance.',\n                    \"2. Supported documents\",\n                    \"FaceSign supports thousands of document types from over 200 countries and territories. The user interface will automatically adapt to show the correct document types based on the user's selected country.\",\n                    \"3. Image quality\",\n                    \"Advise users to place their document on a flat, dark surface in a well-lit area to ensure high-quality captures and accurate data extraction. The SDK provides real-time feedback to help with this.\",\n                    \"4. Data privacy\",\n                    \"Be transparent with users about what data you are collecting and why. Only store the data you need for legal or compliance reasons and handle it securely.\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Identity Verification - Add biometric face matching to your flow\",\n                    \"Proof of Intent - Capture user consent for data collection\",\n                    \"Sessions - Learn more about session management and reports\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/modules/email-verification\",\n        \"sections\": [\n            [\n                \"Email Verification Module\",\n                null,\n                [\n                    \"The Email Verification module sends a one-time password (OTP) to a user's email address to confirm ownership. This is a crucial step for user onboarding, account recovery, and preventing fraudulent sign-ups.\"\n                ]\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"Initiate session - Create a session with the emailVerification module, providing the user's email address.\",\n                    \"OTP sent - FaceSign sends a secure, time-sensitive OTP to the specified email address.\",\n                    \"User enters OTP - The user retrieves the OTP from their email and enters it into the verification interface.\",\n                    \"Verification confirmed - FaceSign verifies the OTP and completes the module, confirming email ownership.\"\n                ]\n            ],\n            [\n                \"Module configuration\",\n                \"module-configuration\",\n                [\n                    \"Properties\",\n                    \"Must be emailVerification.\",\n                    \"The user's name, used to personalize the verification email.\",\n                    \"The user's email address. If not provided, the user will be prompted to enter it.\",\n                    \"If set to true, enables public recognition features. Defaults to false.\"\n                ]\n            ],\n            [\n                \"Example implementations\",\n                \"example-implementations\",\n                [\n                    \"Basic email verification\",\n                    \"A simple setup where the user is prompted to enter their email address:\",\n                    \"Pre-filled and personalized email verification\",\n                    \"For a smoother user experience, pre-fill the user's email and personalize the message:\"\n                ]\n            ],\n            [\n                \"User experience\",\n                \"user-experience\",\n                [\n                    \"Standard flow\",\n                    \"When the email is pre-filled, the user is immediately asked to check their inbox:\",\n                    \"Email verification flow\",\n                    \"Manual entry flow\",\n                    \"If the email is not pre-filled, the user is first prompted to enter their email address:\",\n                    \"Email manual entry flow\",\n                    \"OTP email template\",\n                    \"The email sent to the user contains the OTP and instructions:\",\n                    \"Email OTP template\"\n                ]\n            ],\n            [\n                \"Handling verification results\",\n                \"handling-verification-results\",\n                [\n                    \"Webhook event\",\n                    \"After the user completes the verification, you'll receive a session.completed webhook. Check the extractedData field in the session report for the verified email.\",\n                    \"Backend logic\",\n                    \"Use the webhook to update your database and trigger business logic:\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"1. Pre-fill email address\",\n                    \"Always pre-fill the email address when possible to reduce user friction and improve conversion rates.\",\n                    \"2. Handle invalid emails\",\n                    \"If the user enters an invalid email format, the interface will provide immediate feedback. Ensure your system can handle cases where users correct their email address.\",\n                    \"3. OTP security\",\n                    \"Time-sensitive: OTPs expire after 10 minutes.\",\n                    \"Rate limiting: Users are prevented from requesting too many OTPs in a short period.\",\n                    \"Single-use: Each OTP can only be used once.\",\n                    \"4. Combining with other modules\",\n                    \"For stronger verification, combine email verification with other modules like identityVerification or smsVerification.\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"SMS Verification - Add phone number verification\",\n                    \"Identity Verification - Implement biometric verification\",\n                    \"Sessions - Learn more about session management\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/modules/identity-verification\",\n        \"sections\": [\n            [\n                \"Identity Verification Module\",\n                null,\n                [\n                    \"The Identity Verification module is FaceSign's core biometric verification solution. It uses advanced AI to perform facial recognition and liveness detection, ensuring that the person behind the screen is real, present, and who they claim to be. This module is essential for preventing identity fraud, account takeovers, and deepfake attacks.\"\n                ]\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"Initiate session - Create a session including the identityVerification module.\",\n                    \"User consent - The user is prompted to grant access to their camera.\",\n                    \"Conversational interaction - An AI avatar guides the user through a series of actions, such as looking in different directions or repeating a phrase.\",\n                    \"Biometric analysis - FaceSign analyzes the video feed for liveness, 3D face mapping, and comparison against known data (if applicable).\",\n                    \"Verification complete - The module completes with a detailed report on the verification outcome.\"\n                ]\n            ],\n            [\n                \"Module configuration\",\n                \"module-configuration\",\n                [\n                    \"Properties\",\n                    \"Must be identityVerification.\",\n                    \"This module has no additional configuration properties. Its behavior is determined by the overall session settings and the user's interaction.\"\n                ]\n            ],\n            [\n                \"Example implementation\",\n                \"example-implementation\",\n                [\n                    \"Standard identity verification\",\n                    \"Add the identityVerification module to your session to enable biometric checks.\"\n                ]\n            ],\n            [\n                \"User experience\",\n                \"user-experience\",\n                [\n                    \"Camera access and guidance\",\n                    \"The interface clearly explains why camera access is needed and guides the user through the process.\",\n                    \"Identity verification guidance\",\n                    \"Liveness detection\",\n                    \"The user interacts with the AI avatar to prove they are a real person, present during the verification.\",\n                    \"Identity verification liveness check\",\n                    \"Real-time feedback\",\n                    \"The system provides real-time feedback to help the user position themselves correctly.\",\n                    \"Identity verification real-time feedback\"\n                ]\n            ],\n            [\n                \"Handling verification results\",\n                \"handling-verification-results\",\n                [\n                    \"Webhook event\",\n                    \"The session.completed webhook contains detailed results in the report object.\",\n                    \"Backend logic\",\n                    \"Use the webhook to assess the verification outcome and take appropriate action.\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"1. Clear communication\",\n                    \"Inform your users why they need to complete a biometric verification step. Explain the security benefits to build trust.\",\n                    \"2. Combine with document authentication\",\n                    \"For Know Your Customer (KYC) compliance, combine identityVerification with documentAuthentication to match the user's face to their government-issued ID.\",\n                    \"3. Handling low-light conditions\",\n                    \"FaceSign's AI is designed to work in various lighting conditions, but it's helpful to advise users to be in a well-lit area for the best results.\",\n                    \"4. Deepfake and fraud prevention\",\n                    \"This module is your first line of defense against deepfakes, presentation attacks (e.g., holding up a photo), and other forms of identity fraud. The livenessDetected and realPersonOrVirtual fields are critical for assessing this risk.\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Document Authentication - Add ID document scanning and verification\",\n                    \"Age Estimation - Verify user age with AI\",\n                    \"Custom Flows - Build advanced flows with conditional logic\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/modules/knowledge-verify\",\n        \"sections\": [\n            [\n                \"Knowledge Verify Module\",\n                null,\n                [\n                    \"The Knowledge Verify module adds a layer of security by asking the user questions that only they should know the answer to. This is commonly known as Knowledge-Based Authentication (KBA) and is effective for account recovery, step-up authentication for high-risk actions, and fraud prevention.\"\n                ]\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"Initiate session - Create a session with the knowledgeVerify module.\",\n                    \"Data sources - FaceSign securely accesses trusted data sources to generate out-of-wallet questions based on the user's public and private records.\",\n                    \"Question presented - The AI avatar presents a series of multiple-choice questions to the user.\",\n                    \"User answers - The user selects the correct answer for each question.\",\n                    \"Verification complete - The module completes based on the number of correctly answered questions.\"\n                ]\n            ],\n            [\n                \"Module configuration\",\n                \"module-configuration\",\n                [\n                    \"Properties\",\n                    \"Must be knowledgeVerify.\",\n                    \"This module has no additional configuration properties. The questions are generated dynamically based on available data for the user being verified.\"\n                ]\n            ],\n            [\n                \"Example implementation\",\n                \"example-implementation\",\n                [\n                    \"Account recovery\",\n                    \"Use KBA as a step in a secure account recovery flow.\",\n                    \"Step-up authentication\",\n                    \"Require KBA for high-risk actions like changing an address or adding a new payment method.\"\n                ]\n            ],\n            [\n                \"User experience\",\n                \"user-experience\",\n                [\n                    \"The AI avatar presents a series of multiple-choice questions in a conversational manner.\",\n                    \"Knowledge verify user experience\"\n                ]\n            ],\n            [\n                \"Handling verification results\",\n                \"handling-verification-results\",\n                [\n                    \"Webhook event\",\n                    \"The session.completed webhook report.isVerified field will be true if the user answered enough questions correctly.\",\n                    \"Backend logic\",\n                    \"Use the webhook to determine if the user passed the KBA check.\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"1. Use for step-up or recovery, not onboarding\",\n                    \"KBA is most effective when you already have some information about the user. It is not recommended for initial onboarding of new, unknown users, as there may not be enough data to generate questions.\",\n                    \"2. Combine with other factors\",\n                    \"KBA is strongest when used as part of a multi-factor authentication flow. Combine it with emailVerification, smsVerification, or identityVerification.\",\n                    \"3. Dynamic KBA (D-KBA)\",\n                    \"FaceSign uses dynamic KBA, meaning the questions are generated in real-time from a wide range of data sources. This is more secure than static KBA, which uses a fixed set of questions that could be compromised.\",\n                    '4. Handling \"I don\\'t know\"',\n                    \"The interface allows users to indicate if none of the answers are correct or if they don't know the answer. This is an important part of the process and helps prevent users from guessing.\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Proof of Intent - Capture user consent for high-risk actions\",\n                    \"Custom Flows - Build custom account recovery and step-up authentication flows\",\n                    \"Sessions - Learn more about session management and reports\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/modules/proof-of-intent\",\n        \"sections\": [\n            [\n                \"Proof of Intent Module\",\n                null,\n                [\n                    \"The Proof of Intent module provides a robust, auditable way to capture a user's explicit consent or agreement to specific statements. It uses a combination of conversational AI and video recording to create a durable record of the user's intent, which is essential for legal agreements, high-value transactions, and compliance.\"\n                ]\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"Initiate session - Create a session with the proofOfIntent module, defining the statements you need the user to agree to.\",\n                    \"Avatar presents statements - The AI avatar clearly presents each statement to the user one by one.\",\n                    'User agrees verbally - The user must verbally agree to each required statement (e.g., by saying \"I agree,\" \"Yes,\" or \"I consent\").',\n                    \"Video record created - The entire interaction is video recorded, creating an undeniable record of the user's consent.\",\n                    \"Verification complete - The module completes, and the results are available in the session report.\"\n                ]\n            ],\n            [\n                \"Module configuration\",\n                \"module-configuration\",\n                [\n                    \"Properties\",\n                    \"Must be proofOfIntent.\",\n                    \"An array of RequestedData objects, each representing a statement for the user to agree to.\",\n                    \"RequestedData object\",\n                    \"A unique identifier for the statement. This key will be used in the extractedData of the session report.\",\n                    \"The full text of the statement that will be presented to the user.\",\n                    \"Whether the user must agree to this statement for the verification to be successful. Defaults to true.\"\n                ]\n            ],\n            [\n                \"Example implementations\",\n                \"example-implementations\",\n                [\n                    \"Terms of service and privacy policy\",\n                    \"Capture consent for legal agreements during user onboarding.\",\n                    \"High-value transaction confirmation\",\n                    \"Confirm a large financial transaction to prevent disputes.\"\n                ]\n            ],\n            [\n                \"User experience\",\n                \"user-experience\",\n                [\n                    \"The AI avatar presents each statement clearly, and the user responds verbally.\",\n                    \"Proof of intent user experience\"\n                ]\n            ],\n            [\n                \"Handling verification results\",\n                \"handling-verification-results\",\n                [\n                    \"Webhook event\",\n                    \"The session.completed webhook report contains the user's responses in the extractedData field. The video recording is also available for audit purposes.\",\n                    \"Backend logic\",\n                    \"Use the webhook to record the user's consent and proceed with the action they agreed to.\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"1. Clear and concise statements\",\n                    \"Phrase your statements as clear, unambiguous yes/no questions. Avoid legal jargon where possible.\",\n                    \"2. Required vs. optional consent\",\n                    \"Carefully distinguish between required agreements (like terms of service) and optional ones (like marketing consent) using the isRequired flag.\",\n                    \"3. Audit trail\",\n                    \"Store the userVideoUrl from the session report as part of your audit trail. This provides irrefutable proof of consent.\",\n                    \"4. Combine with Identity Verification\",\n                    \"For maximum legal protection, combine proofOfIntent with identityVerification and documentAuthentication to prove not only what was agreed to, but also who agreed to it.\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Identity Verification - Verify the identity of the person providing consent\",\n                    \"Knowledge Verify - Add knowledge-based questions for further assurance\",\n                    \"Custom Flows - Create complex agreement workflows\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/modules/sms-verification\",\n        \"sections\": [\n            [\n                \"SMS Verification Module\",\n                null,\n                [\n                    \"The SMS Verification module confirms ownership of a phone number by sending a one-time password (OTP) via text message. It's a common and effective method for two-factor authentication (2FA), account recovery, and ensuring you have a valid contact number for your users.\"\n                ]\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"Initiate session - Create a session with the smsVerification module, optionally providing the user's phone number.\",\n                    \"User provides number - If not pre-filled, the user enters their phone number in the verification interface.\",\n                    \"OTP sent - FaceSign sends a secure, time-sensitive OTP to the user's phone.\",\n                    \"User enters OTP - The user enters the OTP from the text message into the interface.\",\n                    \"Verification confirmed - FaceSign validates the OTP and completes the module.\"\n                ]\n            ],\n            [\n                \"Module configuration\",\n                \"module-configuration\",\n                [\n                    \"Properties\",\n                    \"Must be smsVerification.\",\n                    \"The user's phone number in E.164 format (e.g., +14155552671). If not provided, the user will be prompted to enter it.\"\n                ]\n            ],\n            [\n                \"Example implementations\",\n                \"example-implementations\",\n                [\n                    \"Basic SMS verification\",\n                    \"A simple setup where the user is prompted to enter their phone number:\",\n                    \"Pre-filled SMS verification\",\n                    \"To streamline the process, pre-fill the user's phone number:\"\n                ]\n            ],\n            [\n                \"User experience\",\n                \"user-experience\",\n                [\n                    \"Phone number entry\",\n                    \"The interface includes a country code selector for easy and accurate phone number entry:\",\n                    \"SMS phone number entry\",\n                    \"OTP entry\",\n                    \"The user enters the OTP they received via text message:\",\n                    \"SMS OTP entry\",\n                    \"OTP message template\",\n                    \"The text message sent to the user is clear and concise:\",\n                    \"SMS OTP message\"\n                ]\n            ],\n            [\n                \"Handling verification results\",\n                \"handling-verification-results\",\n                [\n                    \"Webhook event\",\n                    \"After successful verification, you'll receive a session.completed webhook. The verified phone number will be in the extractedData field of the session report.\",\n                    \"Backend logic\",\n                    \"Update your database with the verified phone number upon receiving the webhook:\"\n                ]\n            ],\n            [\n                \"Best practices\",\n                \"best-practices\",\n                [\n                    \"1. Pre-fill phone number\",\n                    \"Whenever possible, pre-fill the phone number to simplify the process for users.\",\n                    \"2. E.164 format\",\n                    \"Always provide phone numbers in E.164 format to ensure proper delivery of SMS messages across the globe.\",\n                    \"3. Combining with other modules\",\n                    \"SMS verification is often used as a second factor of authentication. Combine it with emailVerification or identityVerification for enhanced security.\",\n                    \"4. Cost considerations\",\n                    \"Be aware that SMS messages have carrier costs, which may vary by country. FaceSign optimizes for deliverability and cost-effectiveness.\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                [\n                    \"Email Verification - Add email verification to your flow\",\n                    \"Identity Verification - Implement biometric verification for higher security\",\n                    \"Webhooks - Learn more about handling real-time notifications\"\n                ]\n            ]\n        ]\n    }\n];\nfor (let { url, sections } of data){\n    for (let [title, hash, content] of sections){\n        sectionIndex.add({\n            url: url + (hash ? \"#\" + hash : \"\"),\n            title,\n            content: [\n                title,\n                ...content\n            ].join(\"\\n\"),\n            pageTitle: hash ? sections[0][0] : undefined\n        });\n    }\n}\nfunction search(query, options = {}) {\n    let result = sectionIndex.search(query, {\n        ...options,\n        enrich: true\n    });\n    if (result.length === 0) {\n        return [];\n    }\n    return result[0].result.map((item)=>({\n            url: item.id,\n            title: item.doc.title,\n            pageTitle: item.doc.pageTitle\n        }));\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/mdx/search.mjs\n");

